MODEL (
  name silver.item,
  kind FULL,
  grain (item_id),
  audits (item_key_unique, item_net_price_reconcile)
);

SELECT
  CAST(id AS TEXT) AS item_id,
  CAST(CAST(CAST(total AS DECIMAL(12, 4)) AS DECIMAL(38, 9)) / CAST(qty AS BIGINT) AS DECIMAL(12, 4)) AS net_price,
  CAST(price AS DECIMAL(12, 4)) AS net_price__direct,
  CAST(qty AS BIGINT) AS quantity,
  CAST([] AS TEXT[]) AS _quality_flags,
  TRUE AS _quality_ok
FROM bronze.shop__items
